    max_energies = {1: 0, 2: beads[0] * beads[1] * beads[-1]}

    # Iterate over the lengths of the necklace
    for i in range(3, len(beads) + 1):
        # Initialize the maximum energy for this length
        max_energy = 0

        # Iterate over the starting indices of the necklace
        for j in range(i):
