    memo[last] = count
    return count

def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of pairs of positive integers (P, Q)
    such that P and Q have x0 as their greatest common divisor (GCD)
    and y0 as their least common multiple (LCM).
    """
    count = 0
    for a in range(1, y0 // x0 + 1):
