def minimum_cost_to_merge_fruits(fruit_counts: List[int]) -> int:
    # Build min heap using the fruit counts
    heap = []
    for i in range(len(fruit_counts)):
        heapq.heappush(heap, (fruit_counts[i], i))

    # Merge heaps in a greedy manner
    merged_heap = []
    while len(heap) > 1:
        (weight1, i1), (weight2, i2) = heapq.heappop(heap), heapq.heappop(heap)
        merged_heap.append(max(weight1, weight2))
        if len(heap) > 0:
            heapq.heappush(heap, (heapq.heappop(heap)[0] - max(weight1, weight2), i1))

    return sum(merged_heap)
